// Some portions generated by Claude
import { parseSparqlResponse } from "./rdf-results.ts";

export type SparqlResponse = ReturnType<typeof parseSparqlResponse>;
import { QueryFailure } from "./request-batching.ts";

/**
 * The Workbench endpoint the explorer talks to: {basePath}/repositories/{id}/graph, served by
 * org.eclipse.rdf4j.workbench.commands.GraphServlet. It accepts one SPARQL SELECT, CONSTRUCT or DESCRIBE per POST and
 * answers with SPARQL Results JSON (statements of graph queries as ?source ?predicate ?target); the Workbench session (cookies) carries the server credentials, so the browser never sees them.
 */
export function graphEndpoint(basePath: string, repositoryId: string): string {
  return `${(basePath || "").replace(/\/+$/, "")}/repositories/${encodeURIComponent(repositoryId)}/graph`;
}

/** The Workbench page model of the repository's namespaces (WorkbenchNamespaceMetadataServlet). */
export function namespacesEndpoint(basePath: string, repositoryId: string): string {
  return `${(basePath || "").replace(/\/+$/, "")}/repositories/${encodeURIComponent(repositoryId)}/_internal/namespaces`;
}

const termText = (term: unknown): string | undefined =>
  typeof term === "string" ? term
    : term && typeof term === "object" && typeof (term as { value?: unknown }).value === "string"
      ? (term as { value: string }).value : undefined;

/** The prefix/namespace pairs of the Workbench NDJSON page model (vars prefix and namespace, positional rows). */
export function parseNamespaceRows(body: string): { prefix: string; name: string }[] {
  const result: { prefix: string; name: string }[] = [];
  let vars: string[] = [];
  for (const line of body.split("\n")) {
    if (!line.trim()) continue;
    let record: { type?: unknown; values?: unknown };
    try {
      record = JSON.parse(line);
    } catch {
      return [];
    }
    if (record.type === "vars" && Array.isArray(record.values)) vars = record.values.map(String);
    else if (record.type === "rows" && Array.isArray(record.values)) {
      const prefixIndex = vars.indexOf("prefix");
      const nameIndex = vars.indexOf("namespace") >= 0 ? vars.indexOf("namespace") : vars.indexOf("name");
      if (prefixIndex < 0 || nameIndex < 0) continue;
      for (const row of record.values) {
        if (!Array.isArray(row)) continue;
        const prefix = termText(row[prefixIndex]);
        const name = termText(row[nameIndex]);
        if (prefix !== undefined && name) result.push({ prefix: prefix.replace(/:$/, ""), name });
      }
    }
  }
  return result;
}

/** Fetch the repository's namespaces; a failure is an empty list (the built-in prefixes remain). */
export async function fetchNamespaces(basePath: string, repositoryId: string, signal?: AbortSignal) {
  try {
    const response = await fetch(namespacesEndpoint(basePath, repositoryId), {
      headers: { accept: "application/vnd.rdf4j.workbench+ndjson" },
      credentials: "same-origin",
      signal,
    });
    if (!response.ok) return [];
    return parseNamespaceRows(await response.text());
  } catch {
    return [];
  }
}

/** The Workbench Query page with the editor prefilled (WorkbenchViewRegistry.requestsQueryPagePrefill). */
export function queryPageUrl(basePath: string, repositoryId: string, query: string): string {
  return `${(basePath || "").replace(/\/+$/, "")}/repositories/${encodeURIComponent(repositoryId)}/query?query=${encodeURIComponent(query)}`;
}

/** The Workbench Explore page for one resource (an IRI or a literal in N-Triples form). */
export function explorePageUrl(basePath: string, repositoryId: string, resource: string): string {
  return `${(basePath || "").replace(/\/+$/, "")}/repositories/${encodeURIComponent(repositoryId)}/explore?resource=${encodeURIComponent(resource)}`;
}

const STATUS_MESSAGES: Record<number, string> = {
  400: "The repository rejected the query.",
  403: "Query execution is disabled by the Workbench policy.",
  404: "The repository was not found.",
  408: "The query took too long.",
  413: "The query is too long for the Workbench.",
  503: "The Workbench policy is invalid; the administrator must fix workbench.properties.",
};

/** Direct/standalone mounts obtain the same authoritative identity as the normal page-model route. */
export async function resolveServerIdentity(endpoint: string, signal?: AbortSignal): Promise<string> {
  const response = await fetch(endpoint, {
    headers: { accept: "application/vnd.rdf4j.workbench+ndjson" },
    credentials: "same-origin",
    cache: "no-store",
    signal,
  });
  const identity = response.headers.get("X-Workbench-Server-Identity");
  if (!response.ok || !identity) throw new Error("The repository server could not be identified. Reload this page to reconnect.");
  return identity;
}

function csrfTokenFor(endpoint: string): string | null {
  if (typeof document === "undefined" || !document.location) return null;
  if (new URL(endpoint, document.location.href).origin !== document.location.origin) return null;
  const cookie = document.cookie.split(";").map(part => part.trim())
    .find(part => part.startsWith("rdf4j-workbench-csrf="));
  const token = cookie?.substring("rdf4j-workbench-csrf=".length) ?? "";
  return /^[0-9a-f]{64}$/.test(token) ? token : null;
}

export async function queryRepository(endpoint: string, query: string, signal?: AbortSignal, serverIdentity?: string): Promise<SparqlResponse> {
  const csrfToken = csrfTokenFor(endpoint);
  const response = await fetch(endpoint, {
    method: "POST",
    headers: {
      accept: "application/sparql-results+json",
      "content-type": "application/sparql-query; charset=utf-8",
      ...(csrfToken ? { "X-RDF4J-CSRF-Token": csrfToken } : {}),
    },
    body: query,
    credentials: "same-origin",
    signal,
  });
  const body = await response.text();
  if (!response.ok) {
    const detail = body.trim();
    const message = STATUS_MESSAGES[response.status] ?? `The Workbench returned HTTP ${response.status}.`;
    throw new QueryFailure(
      detail && detail.length < 2000 && !detail.startsWith("<") ? `${message} ${detail}` : message,
      response.status,
      Number(response.headers.get("retry-after") ?? 0) * 1000,
    );
  }
  // Another tab can change the server cookie while this graph remains open. Never mix its new results with this
  // graph's saved data or shared metadata; a fresh page model must establish the new server before queries resume.
  if (serverIdentity && response.headers.get("X-Workbench-Server-Identity") !== serverIdentity) {
    throw new QueryFailure("The RDF4J server connection changed. Reload this page to reconnect.", 409);
  }
  try {
    return parseSparqlResponse(body, {repositoryReferences: Boolean(serverIdentity)});
  } catch {
    throw new Error("The Workbench returned a response that was not SPARQL Results JSON.");
  }
}

/** A separate bounded statement count; unknown must keep repository search manual. */
export async function fetchRepositorySize(endpoint: string, serverIdentity: string, signal?: AbortSignal): Promise<number | null> {
  const controller = new AbortController();
  const cancel = () => controller.abort();
  signal?.addEventListener("abort", cancel, { once: true });
  if (signal?.aborted) cancel();
  const deadline = setTimeout(cancel, 5_000);
  try {
    const response = await fetch(`${endpoint}${endpoint.includes("?") ? "&" : "?"}search-size=true`, {
      headers: { accept: "application/json" }, credentials: "same-origin", cache: "no-store", signal: controller.signal,
    });
    if (!response.ok || response.headers.get("X-Workbench-Server-Identity") !== serverIdentity) return null;
    const body: unknown = await response.json();
    if (!body || typeof body !== "object" || !("size" in body)) return null;
    const size = body.size;
    return typeof size === "number" && Number.isSafeInteger(size) && size >= 0 ? size : null;
  } catch {
    // Optional capability: a failed or cancelled probe cannot prevent searching the loaded graph.
    return null;
  } finally {
    clearTimeout(deadline);
    signal?.removeEventListener("abort", cancel);
  }
}
